    /* ---- トップページ ---- */
    "page.top.title": { ja:"MTGアリーナ リミテッド・ワークベンチ｜シールド・ドラフトを無料で練習、勝率データも",
                        en:"MTG Arena Limited Workbench — Free Sealed & Draft practice and win-rate data" },
    "desc.top":       { ja:"マジック：ザ・ギャザリング アリーナのリミテッド専用サイト。仮想パックでシールド・ドラフトを無料で練習でき、友達とのドラフト対人戦や、実戦データによる環境レポート・カード勝率もそろっています。登録不要・日本語対応。",
                        en:"A free site for Magic: The Gathering Arena Limited. Practice Sealed and Draft with virtual packs, draft live with friends, and check set reports and card win rates from real match data. No sign-up needed." },
    "top.h1":    { ja:"MTGアリーナのリミテッドを、もっと楽しく・もっと強く", en:"Play Arena Limited with more fun and more edge" },
    "top.lead":  { ja:"シールド・ドラフトの練習、友達とのドラフト対人戦、実戦データの環境レポートまで。すべて無料、登録も不要です。", en:"Sealed and Draft practice, live drafts with friends, and set reports built on real match data. All free, no account needed." },
    "top.go":    { ja:"開く →", en:"Open →" },
    "top.c1.k":  { ja:"仮想パックで練習", en:"PRACTICE" },
    "top.c2.k":  { ja:"仮想パックで練習", en:"PRACTICE" },
    "top.c3.k":  { ja:"データを見る", en:"DATA" },
    "top.c4.k":  { ja:"仮想パックで練習", en:"PRACTICE" },
    "top.c3.d":  { ja:"セットごとの強い色・速さ・ボムのレアなどを、実戦データで確認できます。", en:"See the strongest colours, the speed and the bomb rares of each set, backed by real match data." },
    "top.latest.h": { ja:"最新のセットの環境レポート", en:"Latest set reports" },
    "top.latest.preview": { ja:"発売直後：速報・下見", en:"Just released: early look" },
    "top.more":  { ja:"セットの一覧を見る →", en:"See all sets →" },
    "top.feat.h":{ ja:"このサイトでできること", en:"What you can do here" },
    "top.t1.p": { ja:"<li>シールド：6パックを開けて40枚のデッキを組む</li><li>ドラフト：CPU 7人との8人卓、または招待リンクで集めた友達との対人戦</li><li>無料。組んだデッキはアリーナにインポート（足りないカードはワイルドカードで）</li><li>スマートフォンでも使えます</li>", en:"<li>Sealed: open six packs and build a 40-card deck</li><li>Draft: an 8-seat table with 7 CPUs, or a live draft with friends you invite by link</li><li>Free. Import the deck into Arena (craft missing cards with wildcards)</li><li>Works on phones too</li>" },
    "top.t2.p": { ja:"<li>アリーナの本番中に、デッキ案とピックのおすすめを出します（アリーナのログを読むだけ）</li><li>シールドのデッキ構築補助：配られたプールから2色のデッキ案</li><li>ドラフトのデッキ構築補助：いま見ているパックのおすすめを理由つきで</li><li>PCのChrome／Edge専用</li>", en:"<li>Deck ideas and pick advice during live Arena events (it just reads Arena's log)</li><li>Sealed deck assistant: two-colour deck ideas from your pool</li><li>Draft deck assistant: the best picks in your pack, with reasons</li><li>PC with Chrome or Edge only</li>" },
    "top.t3.p": { ja:"<li>セットごとの環境の速さと、色・2色の組み合わせの勝率</li><li>レアリティ別の強いカードと、色の組み合わせごとの全勝デッキ</li><li>アリーナ配信の3日後に速報、12日後から勝率と解説動画</li>", en:"<li>Format speed and win rates by colour and colour pair, for each set</li><li>The best cards by rarity, and 7-win decks for each colour pair</li><li>An early look 3 days after the Arena release, then win rates and a video from day 12</li>" },
    "top.t3.video": { ja:"解説動画（YouTube）", en:"Video reviews (YouTube)" },
    "top.t4.p": { ja:"<li>対戦卓：組んだデッキで、ブラウザ上で友達と対戦（ワイルドカードが足りなくても遊べます）</li><li>スイスドロー：対戦会の組み合わせと順位表</li>", en:"<li>Play table: play a friend in the browser with the deck you built (no wildcards needed)</li><li>Swiss pairings: pairings and standings for a get-together</li>" },
    "top.t5.p": { ja:"<li>日本の定番と週替わりのスリーブ・デッキケース・プレイマットを画像つきで</li><li>購入リンクにはアフィリエイトを含みます</li>", en:"<li>Sleeves, deck boxes and playmats sold in Japan, with pictures</li><li>Purchase links include affiliate links</li>" },
    "top.f1":    { ja:"シールド・ドラフトを、仮想パックで何度でも練習", en:"Practice Sealed and Draft as often as you like with virtual packs" },
    "top.f2":    { ja:"セットごとの環境レポートと、カードの勝率一覧", en:"Set reports and card win-rate lists for every set" },
    "top.f3":    { ja:"アリーナの実戦ログを読んで、ピックやデッキ作りを助ける補助ツール（PC）", en:"Helper tools that read your Arena log and guide your picks and deck (PC)" },
    "top.f4":    { ja:"友達と遊べる対戦卓と、スイスドローの進行ツール", en:"A play table for friends and a Swiss-pairing tool for tournaments" },
    "top.f5":    { ja:"環境をまとめた解説動画（YouTube）", en:"Format review videos on YouTube" },
    "top.f6":    { ja:"日本で買えるスリーブ・デッキケースの紹介", en:"Sleeves and deck boxes sold in Japan" },
    "top.moreFaq": { ja:"使い方で迷ったときや、データの更新・デッキ構築補助のことは、<a href=\"./faq.html\">よくある質問</a>にまとめています。", en:"Stuck on how something works, or curious about data updates and the deck assistants? See the <a href=\"./faq.html\">FAQ</a>." },
    "top.new.h": { ja:"MTGがはじめての方へ", en:"New to Magic?" },
    "top.new.p": { ja:"ルールや用語を、やさしい言葉で説明したページと動画を用意しています。", en:"We explain the rules and terms in plain words, in pages and a video." },
