    /* ===== ドラフト・アシスタント ===== */
    "page.assist.title":{ ja:"ドラフトのデッキ構築補助｜アリーナのドラフト中に勝率と色から推奨カードを表示",
                          en:"Draft deck assistant — Live pick suggestions for Arena drafts" },
    "desc.assist":      { ja:"マジック：ザ・ギャザリング アリーナのドラフト中に、いま見ているパックを勝率と自分の色から並べ替えて表示するPC用ツール。ログファイルを読むだけで、画面には触れません。",
                          en:"A PC tool that ranks the pack in front of you during a Magic: The Gathering Arena draft, using real win rates and the colours you are drafting. It reads Arena's log file only." },
    "assist.h1":        { ja:"ドラフトのデッキ構築補助（PC）", en:"Draft deck assistant (PC)" },
    "assist.lead":      { ja:"アリーナのドラフト中に、いま見ているパックのおすすめを勝率と自分の色から順に出し、取ったカードからデッキ案も組みます。PCのChrome／Edge専用です。",
                          en:"During an Arena draft, ranks your current pack by win rate and your colours, and builds a deck idea from your picks. PC Chrome/Edge only." },
    "assist.support": { ja:"<b>対応環境</b>：Windows／MacのPCで、Google Chrome または Microsoft Edge。<b>スマートフォン・タブレット、Firefox・Safariでは使えません。</b>", en:"<b>Requirements</b>: a Windows or Mac PC with Google Chrome or Microsoft Edge. <b>Not available on phones, tablets, Firefox or Safari.</b>" },
    "assist.unsupported":{ ja:"このブラウザでは動きません。PCのChromeまたはEdgeで開いてください。", en:"This browser is not supported. Please open it in Chrome or Edge on a PC." },
    "assist.setupH":    { ja:"準備（初回だけ）", en:"Setup (first time only)" },
    "assist.steps": { ja:"<li>アリーナの設定（右上の歯車）→「アカウント」→「詳細ログ（プラグインのサポート）」にチェックを入れる</li><li>アリーナを再起動する</li><li>下の「Player.log を選ぶ」を押す</li><li>ファイル選択の画面で、上部のアドレス欄に次を貼り付けて Enter<br>Windows：<code>%USERPROFILE%\\AppData\\LocalLow\\Wizards Of The Coast\\MTGA</code><br>Mac：<code>~/Library/Logs/Wizards Of The Coast/MTGA</code></li><li>開いたフォルダの <b>Player.log</b> を選ぶ</li>", en:"<li>In Arena, open Settings (gear, top right) → Account → tick <b>Detailed Logs (Plugin Support)</b></li><li>Restart Arena</li><li>Press “Choose Player.log” below</li><li>In the file dialog, paste this into the address bar and press Enter<br>Windows: <code>%USERPROFILE%\\AppData\\LocalLow\\Wizards Of The Coast\\MTGA</code><br>Mac: <code>~/Library/Logs/Wizards Of The Coast/MTGA</code></li><li>Pick <b>Player.log</b> in that folder</li>" },
    "assist.shotCap":   { ja:"設定 →「アカウント」の画面。「詳細ログ（プラグインのサポート）」にチェックを入れます。", en:"Settings → Account. Tick \"Detailed Logs (Plugin Support)\"." },
    "assist.setupHint": { ja:"ファイルはこのブラウザの中だけで読み、どこにも送りません。パスはそのまま貼れば、自分のフォルダが開きます。", en:"The file is read inside this browser only and never uploaded. Paste the path as it is — it opens your own folder." },
    "assist.pick":      { ja:"Player.log を選ぶ", en:"Choose Player.log" },
    "page.sassist.title":{ ja:"シールドのデッキ構築補助｜アリーナのシールドのプールをログから読み込み、勝率からデッキ案を出す",
                          en:"Sealed deck assistant | Load your Arena sealed pool from the log and get deck suggestions from win rates" },
    "desc.sassist":     { ja:"マジック：ザ・ギャザリング アリーナのシールドで配られたプールを Player.log から読み込み、実戦の勝率と色の噛み合いから2色のデッキ案を組みます。無料。",
                          en:"Load the sealed pool you were dealt in Magic: The Gathering Arena from Player.log and get two-colour deck suggestions built from real win rates. Free." },
    "sassist.h1":       { ja:"シールドのデッキ構築補助（PC）", en:"Sealed deck assistant (PC)" },
    "sassist.lead":     { ja:"アリーナのシールドで配られたプールから、勝率と色の噛み合いで2色のデッキ案を組みます。アリーナのログを読み込むだけで、PCのChrome／Edgeで使えます。",
                          en:"Get two-colour deck ideas, built from win rates and colour fit, for the pool you were dealt in an Arena Sealed event. It just reads Arena's log, in Chrome or Edge on PC." },
    "sassist.support": { ja:"<b>対応環境</b>：PCのアリーナで遊ぶシールド。<b>スマホ版のアリーナでは使えません。</b>", en:"<b>Requirements</b>: sealed events played in Arena on a PC. <b>Not available for the mobile Arena app.</b>" },
    "sassist.steps": { ja:"<li>アリーナの設定（右上の歯車）→「アカウント」→「詳細ログ（プラグインのサポート）」にチェックを入れる</li><li>アリーナを再起動し、シールドに参加してプールを開く（デッキ構築の画面まで進めばOK）</li><li>アリーナを閉じずに、下の「Player.log を選ぶ」を押す</li><li>ファイル選択の画面で、上部のアドレス欄に次を貼り付けて Enter<br>Windows：<code>%USERPROFILE%\\AppData\\LocalLow\\Wizards Of The Coast\\MTGA</code><br>Mac：<code>~/Library/Logs/Wizards Of The Coast/MTGA</code></li><li>開いたフォルダの <b>Player.log</b> を選ぶ</li>", en:"<li>In Arena, open Settings (gear, top right) → Account → tick <b>Detailed Logs (Plugin Support)</b></li><li>Restart Arena, join a sealed event and open your pool (the deck builder screen is enough)</li><li>Without closing Arena, press “Choose Player.log” below</li><li>In the file dialog, paste this into the address bar and press Enter<br>Windows: <code>%USERPROFILE%\\AppData\\LocalLow\\Wizards Of The Coast\\MTGA</code><br>Mac: <code>~/Library/Logs/Wizards Of The Coast/MTGA</code></li><li>Pick <b>Player.log</b> in that folder</li>" },
    "sassist.setupHint": { ja:"ファイルはこのブラウザの中だけで読み、どこにも送りません。アリーナを再起動したときは、シールドのデッキ構築をいちど開き直してください。", en:"The file is read inside this browser only and never uploaded. If you restart Arena, open the sealed deck builder once more." },
